"""JSON files for phase / class / triplet. Not the mask Annotation store."""

from __future__ import annotations

import json
from collections.abc import Callable
from pathlib import Path
from typing import Any

from endo_label.config import Settings

KINDS = ("phase", "class", "triplet")
RENAME_LISTS = {"phases": "phase", "class_tags": "class"}
class TripletFrameCollision(Exception):
    """Renaming a triple would duplicate an exact triple on a Frame."""


_COLUMN_LISTS = ("instruments", "verbs", "targets")
_DEFAULT_VOCAB = {
    "phases": [],
    "class_tags": [],
    "triples": [],
}


def _kind_dir(settings: Settings, kind: str) -> Path:
    if kind not in KINDS:
        raise ValueError(f"unknown kind: {kind}")
    return settings.labels_root / kind


def clip_path(settings: Settings, kind: str, clip_id: str) -> Path:
    if clip_id in ("", ".", "..") or "/" in clip_id or "\\" in clip_id:
        raise ValueError(f"bad clip_id: {clip_id}")
    return _kind_dir(settings, kind) / f"{clip_id}.json"


def vocab_path(settings: Settings) -> Path:
    return settings.labels_root / "vocab.json"


def _read(path: Path, fallback: dict[str, Any]) -> dict[str, Any]:
    if not path.is_file():
        return dict(fallback)
    with path.open("r", encoding="utf-8") as fh:
        data = json.load(fh)
    if not isinstance(data, dict):
        return dict(fallback)
    return data


def _write(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as fh:
        json.dump(data, fh, indent=2, sort_keys=True)
        fh.write("\n")
    tmp.replace(path)


def load_clip(settings: Settings, kind: str, clip_id: str) -> dict[str, Any]:
    path = clip_path(settings, kind, clip_id)
    empty = {"clip_id": clip_id, "frames": {}}
    data = _read(path, empty)
    data.setdefault("clip_id", clip_id)
    data.setdefault("frames", {})
    return data


def save_clip(settings: Settings, kind: str, clip_id: str, data: dict[str, Any]) -> None:
    data = dict(data)
    data["clip_id"] = clip_id
    data.setdefault("frames", {})
    _write(clip_path(settings, kind, clip_id), data)


def _same_triple(row: Any, instrument: str, verb: str, target: str) -> bool:
    return (
        isinstance(row, dict)
        and row.get("instrument") == instrument
        and row.get("verb") == verb
        and row.get("target") == target
    )


def vocab_has_triple(vocab: dict[str, Any], instrument: str, verb: str, target: str) -> bool:
    return any(_same_triple(row, instrument, verb, target) for row in vocab.get("triples") or [])


def _canonical_vocab(data: dict[str, Any]) -> dict[str, Any]:
    triples: list[dict[str, str]] = []
    for row in data.get("triples") or []:
        if not isinstance(row, dict):
            continue
        instrument = row.get("instrument")
        verb = row.get("verb")
        target = row.get("target")
        if isinstance(instrument, str) and isinstance(verb, str) and isinstance(target, str):
            triples.append({"instrument": instrument, "verb": verb, "target": target})
    return {
        "phases": list(data.get("phases") or []),
        "class_tags": list(data.get("class_tags") or []),
        "triples": triples,
    }


def _unique_triples_from_clips(settings: Settings) -> list[dict[str, str]]:
    seen: set[tuple[str, str, str]] = set()
    out: list[dict[str, str]] = []
    for path in _kind_json_paths(settings, "triplet"):
        data = _read(path, {"clip_id": path.stem, "frames": {}})
        frames = data.get("frames") or {}
        for key in sorted(frames, key=lambda item: int(item) if str(item).isdigit() else str(item)):
            for row in frames.get(key) or []:
                if not isinstance(row, dict):
                    continue
                instrument = row.get("instrument")
                verb = row.get("verb")
                target = row.get("target")
                if not isinstance(instrument, str) or not isinstance(verb, str) or not isinstance(target, str):
                    continue
                item = (instrument, verb, target)
                if item in seen:
                    continue
                seen.add(item)
                out.append({"instrument": instrument, "verb": verb, "target": target})
    return out


def load_vocab(settings: Settings) -> dict[str, Any]:
    raw = _read(vocab_path(settings), _DEFAULT_VOCAB)
    if any(key in raw for key in _COLUMN_LISTS):
        migrated = {
            "phases": list(raw.get("phases") or []),
            "class_tags": list(raw.get("class_tags") or []),
            "triples": _unique_triples_from_clips(settings),
        }
        save_vocab(settings, migrated)
        return migrated
    return _canonical_vocab(raw)


def save_vocab(settings: Settings, data: dict[str, Any]) -> None:
    _write(vocab_path(settings), _canonical_vocab(data))


def _kind_json_paths(settings: Settings, kind: str) -> list[Path]:
    folder = _kind_dir(settings, kind)
    if not folder.is_dir():
        return []
    return sorted(path for path in folder.glob("*.json") if path.is_file())


def _rewrite_frames(kind: str, frames: dict[str, Any], old: str, new: str) -> dict[str, Any]:
    rewritten: dict[str, Any] = {}
    for key, value in frames.items():
        if kind == "phase":
            rewritten[key] = new if value == old else value
            continue
        tags = [new if tag == old else tag for tag in (value or [])]
        tags = list(dict.fromkeys(tags))
        if tags:
            rewritten[key] = tags
    return rewritten


def _pending_clip_rewrites(
    settings: Settings,
    kind: str,
    rewrite: Callable[[dict[str, Any]], dict[str, Any]],
) -> list[tuple[Path, dict[str, Any]]]:
    pending: list[tuple[Path, dict[str, Any]]] = []
    for path in _kind_json_paths(settings, kind):
        data = _read(path, {"clip_id": path.stem, "frames": {}})
        frames = data.get("frames") or {}
        rewritten = rewrite(frames)
        if rewritten == frames:
            continue
        data = dict(data)
        data.setdefault("clip_id", path.stem)
        data["frames"] = rewritten
        pending.append((path, data))
    return pending


def _commit_rewritten_clips_and_vocab(
    settings: Settings,
    pending: list[tuple[Path, dict[str, Any]]],
    vocab: dict[str, Any],
) -> dict[str, Any]:
    backups: list[tuple[Path, bytes | None]] = []
    try:
        for path, data in pending:
            backups.append((path, path.read_bytes() if path.is_file() else None))
            _write(path, data)
        save_vocab(settings, vocab)
    except Exception:
        for path, blob in reversed(backups):
            if blob is None:
                path.unlink(missing_ok=True)
            else:
                path.write_bytes(blob)
        raise
    return vocab


def rename_vocab_name(settings: Settings, list_name: str, old: str, new: str) -> dict[str, Any]:
    """Rename one list entry and rewrite every Clip document of that kind.

    Clip files are written first, then vocab. On failure, already-replaced
    Clip files are restored so no Clip is left partially renamed.
    """
    kind = RENAME_LISTS[list_name]
    vocab = load_vocab(settings)
    bucket = list(vocab.get(list_name) or [])
    bucket[bucket.index(old)] = new
    vocab[list_name] = bucket
    pending = _pending_clip_rewrites(
        settings,
        kind,
        lambda frames: _rewrite_frames(kind, frames, old, new),
    )
    return _commit_rewritten_clips_and_vocab(settings, pending, vocab)


def _drop_name_from_frames(kind: str, frames: dict[str, Any], name: str) -> dict[str, Any]:
    rewritten: dict[str, Any] = {}
    for key, value in frames.items():
        if kind == "phase":
            if value != name:
                rewritten[key] = value
            continue
        tags = [tag for tag in (value or []) if tag != name]
        if tags:
            rewritten[key] = tags
    return rewritten


def _drop_triple_from_frames(
    frames: dict[str, Any],
    instrument: str,
    verb: str,
    target: str,
) -> dict[str, Any]:
    rewritten: dict[str, Any] = {}
    for key, rows in frames.items():
        kept = [row for row in (rows or []) if not _same_triple(row, instrument, verb, target)]
        if kept:
            rewritten[key] = kept
    return rewritten


def delete_vocab_name(settings: Settings, list_name: str, name: str) -> dict[str, Any]:
    """Remove one list entry. Phase/class rewrite every Clip of that kind.

    Clip files are written first, then vocab. On failure, already-replaced
    Clip files are restored.
    """
    vocab = load_vocab(settings)
    bucket = list(vocab.get(list_name) or [])
    bucket.remove(name)
    vocab[list_name] = bucket
    kind = RENAME_LISTS[list_name]
    pending = _pending_clip_rewrites(
        settings,
        kind,
        lambda frames: _drop_name_from_frames(kind, frames, name),
    )
    return _commit_rewritten_clips_and_vocab(settings, pending, vocab)


def delete_vocab_triple(settings: Settings, instrument: str, verb: str, target: str) -> dict[str, Any]:
    """Remove one exact triple from Vocab and every Clip, or restore all."""
    vocab = load_vocab(settings)
    triples = list(vocab.get("triples") or [])
    kept = [row for row in triples if not _same_triple(row, instrument, verb, target)]
    if len(kept) == len(triples):
        raise KeyError((instrument, verb, target))
    vocab["triples"] = kept
    pending = _pending_clip_rewrites(
        settings,
        "triplet",
        lambda frames: _drop_triple_from_frames(frames, instrument, verb, target),
    )
    return _commit_rewritten_clips_and_vocab(settings, pending, vocab)


def rename_vocab_triple(
    settings: Settings,
    from_inst: str,
    from_verb: str,
    from_target: str,
    to_inst: str,
    to_verb: str,
    to_target: str,
) -> dict[str, Any]:
    """Rename one exact triple and rewrite every matching triplet row across Clips.

    If any Frame would hold two identical triples after rewrite, TripletFrameCollision is raised
    and no files are changed.
    If the target triple already exists in Vocab, ValueError is raised.
    Clip files are written first, then vocab. On failure, modified Clip files are restored.
    """
    vocab = load_vocab(settings)
    triples = list(vocab.get("triples") or [])
    from_idx = -1
    for idx, row in enumerate(triples):
        if _same_triple(row, from_inst, from_verb, from_target):
            from_idx = idx
            break
    if from_idx < 0:
        raise KeyError((from_inst, from_verb, from_target))

    if (from_inst, from_verb, from_target) == (to_inst, to_verb, to_target):
        return vocab

    for path in _kind_json_paths(settings, "triplet"):
        data = _read(path, {"clip_id": path.stem, "frames": {}})
        for frame_key, rows in (data.get("frames") or {}).items():
            from_count = sum(1 for row in (rows or []) if _same_triple(row, from_inst, from_verb, from_target))
            to_count = sum(1 for row in (rows or []) if _same_triple(row, to_inst, to_verb, to_target))
            if from_count > 0 and (to_count > 0 or from_count > 1):
                raise TripletFrameCollision(f"Frame {frame_key} would hold duplicate triple")

    if vocab_has_triple(vocab, to_inst, to_verb, to_target):
        raise ValueError(f"already present: {to_inst} / {to_verb} / {to_target}")

    triples[from_idx] = {"instrument": to_inst, "verb": to_verb, "target": to_target}
    vocab["triples"] = triples

    def _rewrite_frames(frames: dict[str, Any]) -> dict[str, Any]:
        rewritten: dict[str, Any] = {}
        for key, rows in frames.items():
            new_rows: list[dict[str, Any]] = []
            for row in rows or []:
                if _same_triple(row, from_inst, from_verb, from_target):
                    new_rows.append({
                        "id": row.get("id"),
                        "instrument": to_inst,
                        "verb": to_verb,
                        "target": to_target,
                    })
                else:
                    new_rows.append(row)
            rewritten[key] = new_rows
        return rewritten

    pending = _pending_clip_rewrites(settings, "triplet", _rewrite_frames)
    return _commit_rewritten_clips_and_vocab(settings, pending, vocab)

"""Desk-wide customizable name lists for phase / class / triplet."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field

from endo_label.config import Settings
from endo_label import labels_store

_LISTS = ("phases", "class_tags")
_RENAMEABLE = frozenset(labels_store.RENAME_LISTS)


class VocabAddBody(BaseModel):
    name: str = Field(..., min_length=1)


class VocabRenameBody(BaseModel):
    from_name: str = Field(..., alias="from")
    to_name: str = Field(..., alias="to")

    model_config = {"populate_by_name": True}


class VocabTripleBody(BaseModel):
    instrument: str = Field(..., min_length=1)
    verb: str = Field(..., min_length=1)
    target: str = Field(..., min_length=1)


class VocabTripleRenameBody(BaseModel):
    from_triple: VocabTripleBody = Field(..., alias="from")
    to_triple: VocabTripleBody = Field(..., alias="to")

    model_config = {"populate_by_name": True}


def make_router(settings: Settings) -> APIRouter:
    router = APIRouter(tags=["vocab"])

    def _stripped_triple(body: VocabTripleBody) -> tuple[str, str, str]:
        instrument = body.instrument.strip()
        verb = body.verb.strip()
        target = body.target.strip()
        if not instrument or not verb or not target:
            raise HTTPException(status_code=400, detail="empty name")
        return instrument, verb, target

    @router.get("/api/vocab")
    def get_vocab() -> dict:
        return labels_store.load_vocab(settings)

    @router.post("/api/vocab/triples")
    def add_triple(body: VocabTripleBody) -> dict:
        instrument, verb, target = _stripped_triple(body)
        vocab = labels_store.load_vocab(settings)
        if labels_store.vocab_has_triple(vocab, instrument, verb, target):
            raise HTTPException(
                status_code=409,
                detail=f"already present: {instrument} / {verb} / {target}",
            )
        triples = list(vocab.get("triples") or [])
        triples.append({"instrument": instrument, "verb": verb, "target": target})
        vocab["triples"] = triples
        labels_store.save_vocab(settings, vocab)
        return vocab

    @router.delete("/api/vocab/triples")
    def delete_triple(instrument: str, verb: str, target: str) -> dict:
        instrument, verb, target = instrument.strip(), verb.strip(), target.strip()
        if not instrument or not verb or not target:
            raise HTTPException(status_code=400, detail="empty name")
        vocab = labels_store.load_vocab(settings)
        if not labels_store.vocab_has_triple(vocab, instrument, verb, target):
            raise HTTPException(
                status_code=400,
                detail=f"unknown triple: {instrument} / {verb} / {target}",
            )
        return labels_store.delete_vocab_triple(settings, instrument, verb, target)

    @router.post("/api/vocab/triples/rename")
    def rename_triple(body: VocabTripleRenameBody) -> dict:
        from_inst, from_verb, from_targ = _stripped_triple(body.from_triple)
        to_inst, to_verb, to_targ = _stripped_triple(body.to_triple)
        vocab = labels_store.load_vocab(settings)
        if not labels_store.vocab_has_triple(vocab, from_inst, from_verb, from_targ):
            raise HTTPException(
                status_code=400,
                detail=f"unknown triple: {from_inst} / {from_verb} / {from_targ}",
            )
        try:
            return labels_store.rename_vocab_triple(
                settings,
                from_inst,
                from_verb,
                from_targ,
                to_inst,
                to_verb,
                to_targ,
            )
        except labels_store.TripletFrameCollision as err:
            raise HTTPException(status_code=409, detail=str(err)) from None
        except ValueError as err:
            raise HTTPException(status_code=409, detail=str(err)) from None

    @router.post("/api/vocab/{list_name}")
    def add_name(list_name: str, body: VocabAddBody) -> dict:
        if list_name not in _LISTS:
            raise HTTPException(status_code=404, detail=f"unknown list: {list_name}")
        vocab = labels_store.load_vocab(settings)
        name = body.name.strip()
        if not name:
            raise HTTPException(status_code=400, detail="empty name")
        bucket = list(vocab.get(list_name) or [])
        if name in bucket:
            raise HTTPException(status_code=409, detail=f"already present: {name}")
        bucket.append(name)
        vocab[list_name] = bucket
        labels_store.save_vocab(settings, vocab)
        return vocab

    @router.post("/api/vocab/{list_name}/rename")
    def rename_name(list_name: str, body: VocabRenameBody) -> dict:
        if list_name not in _LISTS:
            raise HTTPException(status_code=404, detail=f"unknown list: {list_name}")
        if list_name not in _RENAMEABLE:
            raise HTTPException(status_code=400, detail=f"rename not supported: {list_name}")
        old = body.from_name.strip()
        new = body.to_name.strip()
        if not new:
            raise HTTPException(status_code=400, detail="empty name")
        vocab = labels_store.load_vocab(settings)
        bucket = list(vocab.get(list_name) or [])
        if old not in bucket:
            raise HTTPException(status_code=400, detail=f"unknown name: {old}")
        if new in bucket:
            raise HTTPException(status_code=409, detail=f"already present: {new}")
        return labels_store.rename_vocab_name(settings, list_name, old, new)

    @router.delete("/api/vocab/{list_name}/{name}")
    def delete_name(list_name: str, name: str) -> dict:
        if list_name not in _LISTS:
            raise HTTPException(status_code=404, detail=f"unknown list: {list_name}")
        vocab = labels_store.load_vocab(settings)
        bucket = list(vocab.get(list_name) or [])
        if name not in bucket:
            raise HTTPException(status_code=400, detail=f"unknown name: {name}")
        return labels_store.delete_vocab_name(settings, list_name, name)

    return router

""" /api/registry — Vocab registry, enablement, candidates (writes admin-only). """

from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException, Request
from pydantic import BaseModel

from endo_label.auth import require_admin
from endo_label.coordination import Account, ProjectNotFound, db_path
from endo_label.registry import (
    CandidateNotFound,
    RegistryConflict,
    RegistryItemNotFound,
    browse_payload,
    create_candidate,
    create_item,
    edit_candidate,
    promote_candidate,
    rename_item,
    set_archived,
    set_enabled,
    visible_items,
)

router = APIRouter()


class RegistryWriteBody(BaseModel):
    kind: str = ""
    name: str = ""
    instrument: str = ""
    verb: str = ""
    target: str = ""


class CandidateWriteBody(RegistryWriteBody):
    project_id: int | None = None


class ProjectBody(BaseModel):
    project_id: int


def _path(request: Request):
    return db_path(request.app.state.settings)


def _http(exc: Exception) -> HTTPException:
    if isinstance(exc, ValueError):
        return HTTPException(status_code=400, detail=str(exc))
    if isinstance(exc, (RegistryItemNotFound, CandidateNotFound, ProjectNotFound)):
        return HTTPException(status_code=404, detail=str(exc))
    if isinstance(exc, RegistryConflict):
        return HTTPException(status_code=409, detail=f"already present: {exc}")
    raise exc


@router.get("/api/registry")
def get_registry(request: Request) -> dict:
    return browse_payload(_path(request))


@router.get("/api/registry/visible")
def get_visible(request: Request, project_id: int) -> dict:
    try:
        items = visible_items(_path(request), project_id)
    except ProjectNotFound as exc:
        raise _http(exc) from None
    return {"items": [item.as_dict() for item in items]}


@router.post("/api/registry")
def post_item(
    body: RegistryWriteBody,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        item = create_item(
            _path(request),
            body.kind,
            name=body.name,
            instrument=body.instrument,
            verb=body.verb,
            target=body.target,
        )
    except (ValueError, RegistryConflict) as exc:
        raise _http(exc) from None
    return item.as_dict()


@router.post("/api/registry/candidates")
def post_candidate(
    body: CandidateWriteBody,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    if body.project_id is None:
        raise HTTPException(status_code=400, detail="project_id is required")
    try:
        candidate = create_candidate(
            _path(request),
            body.project_id,
            body.kind,
            name=body.name,
            instrument=body.instrument,
            verb=body.verb,
            target=body.target,
        )
    except (ValueError, ProjectNotFound) as exc:
        raise _http(exc) from None
    return candidate.as_dict()


@router.post("/api/registry/candidates/{candidate_id}")
def post_edit_candidate(
    candidate_id: int,
    body: RegistryWriteBody,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        candidate = edit_candidate(
            _path(request),
            candidate_id,
            name=body.name,
            instrument=body.instrument,
            verb=body.verb,
            target=body.target,
        )
    except (ValueError, CandidateNotFound) as exc:
        raise _http(exc) from None
    return candidate.as_dict()


@router.post("/api/registry/candidates/{candidate_id}/promote")
def post_promote(
    candidate_id: int,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        item = promote_candidate(_path(request), candidate_id)
    except (CandidateNotFound, RegistryConflict) as exc:
        raise _http(exc) from None
    return item.as_dict()


@router.post("/api/registry/{vocab_id}/rename")
def post_rename(
    vocab_id: int,
    body: RegistryWriteBody,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        item = rename_item(
            _path(request),
            vocab_id,
            name=body.name,
            instrument=body.instrument,
            verb=body.verb,
            target=body.target,
        )
    except (ValueError, RegistryItemNotFound, RegistryConflict) as exc:
        raise _http(exc) from None
    return item.as_dict()


@router.post("/api/registry/{vocab_id}/archive")
def post_archive(
    vocab_id: int,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        item = set_archived(_path(request), vocab_id, True)
    except (RegistryItemNotFound, RegistryConflict) as exc:
        raise _http(exc) from None
    return item.as_dict()


@router.post("/api/registry/{vocab_id}/restore")
def post_restore(
    vocab_id: int,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        item = set_archived(_path(request), vocab_id, False)
    except (RegistryItemNotFound, RegistryConflict) as exc:
        raise _http(exc) from None
    return item.as_dict()


@router.post("/api/registry/{vocab_id}/enable")
def post_enable(
    vocab_id: int,
    body: ProjectBody,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        set_enabled(_path(request), vocab_id, body.project_id, True)
    except (RegistryItemNotFound, ProjectNotFound) as exc:
        raise _http(exc) from None
    return {"ok": True}


@router.post("/api/registry/{vocab_id}/disable")
def post_disable(
    vocab_id: int,
    body: ProjectBody,
    request: Request,
    _: Account = Depends(require_admin),
) -> dict:
    try:
        set_enabled(_path(request), vocab_id, body.project_id, False)
    except (RegistryItemNotFound, ProjectNotFound) as exc:
        raise _http(exc) from None
    return {"ok": True}

"""Phase HTTP: exclusive label per Frame; optional span write."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field

from endo_label import catalog
from endo_label.config import Settings
from endo_label import labels_store


class PhaseSpanBody(BaseModel):
    phase: str | None = Field(...)
    from_frame: int = Field(..., ge=0, alias="from")
    to_frame: int = Field(..., ge=0, alias="to")

    model_config = {"populate_by_name": True}


class PhaseFrameBody(BaseModel):
    phase: str | None = None


def make_router(settings: Settings) -> APIRouter:
    router = APIRouter(tags=["phase"])

    def _meta(clip_id: str) -> dict:
        try:
            return catalog.clip_meta(settings, clip_id)
        except catalog.ClipNotFound:
            raise HTTPException(status_code=404, detail=f"Clip not found: {clip_id}") from None

    def _require_phase_name(name: str) -> None:
        phases = labels_store.load_vocab(settings).get("phases") or []
        if name not in phases:
            raise HTTPException(status_code=400, detail=f"unknown phase: {name}")

    @router.get("/api/phase/{clip_id}")
    def get_clip_phase(clip_id: str) -> dict:
        _meta(clip_id)
        return labels_store.load_clip(settings, "phase", clip_id)

    @router.put("/api/phase/{clip_id}/frames/{frame_index}")
    def put_frame_phase(clip_id: str, frame_index: int, body: PhaseFrameBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        if frame_index < 0 or frame_index >= n:
            raise HTTPException(status_code=404, detail=f"Frame index out of range: {frame_index}")
        doc = labels_store.load_clip(settings, "phase", clip_id)
        key = str(frame_index)
        if body.phase is None:
            doc["frames"].pop(key, None)
        else:
            _require_phase_name(body.phase)
            doc["frames"][key] = body.phase
        labels_store.save_clip(settings, "phase", clip_id, doc)
        return doc

    @router.post("/api/phase/{clip_id}/span")
    def paint_span(clip_id: str, body: PhaseSpanBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        a, b = body.from_frame, body.to_frame
        if a > b:
            a, b = b, a
        if a < 0 or b >= n:
            raise HTTPException(status_code=400, detail="span out of range")
        if body.phase is not None:
            _require_phase_name(body.phase)
        doc = labels_store.load_clip(settings, "phase", clip_id)
        for i in range(a, b + 1):
            key = str(i)
            if body.phase is None:
                doc["frames"].pop(key, None)
            else:
                doc["frames"][key] = body.phase
        labels_store.save_clip(settings, "phase", clip_id, doc)
        return doc

    return router

"""Class HTTP: stackable named flags on a Frame."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field

from endo_label import catalog
from endo_label.config import Settings
from endo_label import labels_store


class ClassBody(BaseModel):
    tags: list[str] = Field(default_factory=list)


class ClassSpanBody(BaseModel):
    tag: str = Field(..., min_length=1)
    from_frame: int = Field(..., ge=0, alias="from")
    to_frame: int = Field(..., ge=0, alias="to")
    on: bool

    model_config = {"populate_by_name": True}


def make_router(settings: Settings) -> APIRouter:
    router = APIRouter(tags=["class"])

    def _meta(clip_id: str) -> dict:
        try:
            return catalog.clip_meta(settings, clip_id)
        except catalog.ClipNotFound:
            raise HTTPException(status_code=404, detail=f"Clip not found: {clip_id}") from None

    def _require_class_name(name: str) -> None:
        tags = labels_store.load_vocab(settings).get("class_tags") or []
        if name not in tags:
            raise HTTPException(status_code=400, detail=f"unknown class: {name}")

    @router.get("/api/class/{clip_id}")
    def get_clip_class(clip_id: str) -> dict:
        _meta(clip_id)
        return labels_store.load_clip(settings, "class", clip_id)

    @router.put("/api/class/{clip_id}/frames/{frame_index}")
    def put_frame_class(clip_id: str, frame_index: int, body: ClassBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        if frame_index < 0 or frame_index >= n:
            raise HTTPException(status_code=404, detail=f"Frame index out of range: {frame_index}")
        doc = labels_store.load_clip(settings, "class", clip_id)
        key = str(frame_index)
        tags = list(dict.fromkeys(body.tags))
        if not tags:
            doc["frames"].pop(key, None)
        else:
            for name in tags:
                _require_class_name(name)
            doc["frames"][key] = tags
        labels_store.save_clip(settings, "class", clip_id, doc)
        return doc

    @router.post("/api/class/{clip_id}/span")
    def paint_span(clip_id: str, body: ClassSpanBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        a, b = body.from_frame, body.to_frame
        if a > b:
            a, b = b, a
        if a < 0 or b >= n:
            raise HTTPException(status_code=400, detail="span out of range")
        _require_class_name(body.tag)

        doc = labels_store.load_clip(settings, "class", clip_id)
        for i in range(a, b + 1):
            key = str(i)
            tags = list(dict.fromkeys(doc["frames"].get(key) or []))
            if body.on:
                if body.tag not in tags:
                    tags.append(body.tag)
            else:
                tags = [tag for tag in tags if tag != body.tag]
            if tags:
                doc["frames"][key] = tags
            else:
                doc["frames"].pop(key, None)
        labels_store.save_clip(settings, "class", clip_id, doc)
        return doc

    return router

"""Triplet HTTP: rows on a Frame, no Track required."""

from __future__ import annotations

from typing import Literal

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field

from endo_label import catalog
from endo_label.config import Settings
from endo_label import labels_store


class TripletBody(BaseModel):
    instrument: str = Field(..., min_length=1)
    verb: str = Field(..., min_length=1)
    target: str = Field(..., min_length=1)


class TripletSpanBody(BaseModel):
    instrument: str = Field(..., min_length=1)
    verb: str = Field(..., min_length=1)
    target: str = Field(..., min_length=1)
    from_frame: int = Field(..., ge=0, alias="from")
    to_frame: int = Field(..., ge=0, alias="to")
    op: Literal["add", "remove"]

    model_config = {"populate_by_name": True}


def make_router(settings: Settings) -> APIRouter:
    router = APIRouter(tags=["triplet"])

    def _meta(clip_id: str) -> dict:
        try:
            return catalog.clip_meta(settings, clip_id)
        except catalog.ClipNotFound:
            raise HTTPException(status_code=404, detail=f"Clip not found: {clip_id}") from None

    def _next_id(rows: list[dict]) -> int:
        if not rows:
            return 1
        return max(int(r.get("id", 0)) for r in rows) + 1

    def _require_vocab_triple(instrument: str, verb: str, target: str) -> None:
        vocab = labels_store.load_vocab(settings)
        if not labels_store.vocab_has_triple(vocab, instrument, verb, target):
            raise HTTPException(
                status_code=400,
                detail=f"unknown triple: {instrument} / {verb} / {target}",
            )

    @router.get("/api/triplet/{clip_id}")
    def get_clip_triplet(clip_id: str) -> dict:
        _meta(clip_id)
        return labels_store.load_clip(settings, "triplet", clip_id)

    @router.post("/api/triplet/{clip_id}/frames/{frame_index}")
    def add_triplet(clip_id: str, frame_index: int, body: TripletBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        if frame_index < 0 or frame_index >= n:
            raise HTTPException(status_code=404, detail=f"Frame index out of range: {frame_index}")
        _require_vocab_triple(body.instrument, body.verb, body.target)
        doc = labels_store.load_clip(settings, "triplet", clip_id)
        key = str(frame_index)
        rows = list(doc["frames"].get(key) or [])

        def _same(row: dict) -> bool:
            return (
                row.get("instrument") == body.instrument
                and row.get("verb") == body.verb
                and row.get("target") == body.target
            )

        if any(_same(row) for row in rows):
            kept = [row for row in rows if not _same(row)]
            if kept:
                doc["frames"][key] = kept
            else:
                doc["frames"].pop(key, None)
            labels_store.save_clip(settings, "triplet", clip_id, doc)
            return {"rows": kept}
        row = {
            "id": _next_id(rows),
            "instrument": body.instrument,
            "verb": body.verb,
            "target": body.target,
        }
        rows.append(row)
        doc["frames"][key] = rows
        labels_store.save_clip(settings, "triplet", clip_id, doc)
        return row

    @router.put("/api/triplet/{clip_id}/frames/{frame_index}/{triplet_id}")
    def put_triplet(clip_id: str, frame_index: int, triplet_id: int, body: TripletBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        if frame_index < 0 or frame_index >= n:
            raise HTTPException(status_code=404, detail=f"Frame index out of range: {frame_index}")
        _require_vocab_triple(body.instrument, body.verb, body.target)
        doc = labels_store.load_clip(settings, "triplet", clip_id)
        key = str(frame_index)
        rows = list(doc["frames"].get(key) or [])
        found = False
        for row in rows:
            if int(row.get("id", -1)) == triplet_id:
                row["instrument"] = body.instrument
                row["verb"] = body.verb
                row["target"] = body.target
                found = True
                break
        if not found:
            raise HTTPException(status_code=404, detail=f"triplet not found: {triplet_id}")
        doc["frames"][key] = rows
        labels_store.save_clip(settings, "triplet", clip_id, doc)
        return doc

    @router.post("/api/triplet/{clip_id}/span")
    def paint_span(clip_id: str, body: TripletSpanBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        a, b = body.from_frame, body.to_frame
        if a > b:
            a, b = b, a
        if a < 0 or b >= n:
            raise HTTPException(status_code=400, detail="span out of range")
        _require_vocab_triple(body.instrument, body.verb, body.target)

        doc = labels_store.load_clip(settings, "triplet", clip_id)
        for i in range(a, b + 1):
            key = str(i)
            rows = list(doc["frames"].get(key) or [])
            if body.op == "add":
                if not any(
                    row.get("instrument") == body.instrument
                    and row.get("verb") == body.verb
                    and row.get("target") == body.target
                    for row in rows
                ):
                    rows.append(
                        {
                            "id": _next_id(rows),
                            "instrument": body.instrument,
                            "verb": body.verb,
                            "target": body.target,
                        }
                    )
            else:
                rows = [
                    row
                    for row in rows
                    if not (
                        row.get("instrument") == body.instrument
                        and row.get("verb") == body.verb
                        and row.get("target") == body.target
                    )
                ]
            if rows:
                doc["frames"][key] = rows
            else:
                doc["frames"].pop(key, None)

        labels_store.save_clip(settings, "triplet", clip_id, doc)
        return doc

    @router.delete("/api/triplet/{clip_id}/frames/{frame_index}/{triplet_id}")
    def delete_triplet(clip_id: str, frame_index: int, triplet_id: int) -> dict:
        _meta(clip_id)
        doc = labels_store.load_clip(settings, "triplet", clip_id)
        key = str(frame_index)
        rows = list(doc["frames"].get(key) or [])
        kept = [r for r in rows if int(r.get("id", -1)) != triplet_id]
        if len(kept) == len(rows):
            raise HTTPException(status_code=404, detail=f"triplet not found: {triplet_id}")
        if kept:
            doc["frames"][key] = kept
        else:
            doc["frames"].pop(key, None)
        labels_store.save_clip(settings, "triplet", clip_id, doc)
        return doc

    return router

"""SQLite coordination store: Accounts, Projects, Clip registration, Vocab registry (WAL)."""

from __future__ import annotations

import secrets
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

from pwdlib import PasswordHash

from endo_label.config import Settings

BUSY_TIMEOUT_MS = 5000

_HASHER = PasswordHash.recommended()


class AccountExists(Exception):
    """Username already taken."""


class ProjectExists(Exception):
    """Project name already taken."""


class ProjectNotFound(Exception):
    """No Project with that name or id."""


class ClipExists(Exception):
    """Clip id already registered."""


@dataclass(frozen=True)
class Account:
    id: int
    username: str
    admin: bool
    reviewer: bool
    annotator: bool
    disabled: bool


@dataclass(frozen=True)
class Project:
    id: int
    name: str
    hospital: str


@dataclass(frozen=True)
class RegisteredClip:
    id: str
    project_id: int
    kind: str
    path: Path

def db_path(settings: Settings) -> Path:
    if settings.coordination_db is not None:
        return settings.coordination_db
    return settings.labels_root.parent / "coordination.sqlite"


def connect(path: Path) -> sqlite3.Connection:
    path.parent.mkdir(parents=True, exist_ok=True)
    con = sqlite3.connect(str(path), check_same_thread=False)
    con.row_factory = sqlite3.Row
    con.execute(f"PRAGMA busy_timeout={BUSY_TIMEOUT_MS}")
    con.execute("PRAGMA foreign_keys=ON")
    mode = con.execute("PRAGMA journal_mode=WAL").fetchone()[0]
    if str(mode).lower() != "wal":
        raise RuntimeError(f"failed to enable WAL: {mode}")
    _init_schema(con)
    return con


def _init_schema(con: sqlite3.Connection) -> None:
    con.executescript(
        """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT NOT NULL UNIQUE COLLATE NOCASE,
            password_hash TEXT NOT NULL,
            admin INTEGER NOT NULL DEFAULT 0 CHECK (admin IN (0, 1)),
            reviewer INTEGER NOT NULL DEFAULT 0 CHECK (reviewer IN (0, 1)),
            annotator INTEGER NOT NULL DEFAULT 0 CHECK (annotator IN (0, 1)),
            disabled INTEGER NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1))
        );
        CREATE TABLE IF NOT EXISTS login_sessions (
            id TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS projects (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL UNIQUE,
            hospital TEXT NOT NULL DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS clips (
            id TEXT PRIMARY KEY,
            project_id INTEGER NOT NULL REFERENCES projects(id),
            kind TEXT NOT NULL,
            path TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS vocab_registry (
            id INTEGER PRIMARY KEY,
            kind TEXT NOT NULL CHECK (kind IN ('phase', 'class', 'triplet')),
            name TEXT NOT NULL DEFAULT '',
            instrument TEXT NOT NULL DEFAULT '',
            verb TEXT NOT NULL DEFAULT '',
            target TEXT NOT NULL DEFAULT '',
            archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
        );
        CREATE TABLE IF NOT EXISTS project_vocab_enabled (
            project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
            vocab_id INTEGER NOT NULL REFERENCES vocab_registry(id) ON DELETE CASCADE,
            PRIMARY KEY (project_id, vocab_id)
        );
        CREATE TABLE IF NOT EXISTS project_vocab_candidates (
            id INTEGER PRIMARY KEY,
            project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
            kind TEXT NOT NULL CHECK (kind IN ('phase', 'class', 'triplet')),
            name TEXT NOT NULL DEFAULT '',
            instrument TEXT NOT NULL DEFAULT '',
            verb TEXT NOT NULL DEFAULT '',
            target TEXT NOT NULL DEFAULT ''
        );
        CREATE UNIQUE INDEX IF NOT EXISTS vocab_registry_active_name
            ON vocab_registry(kind, name)
            WHERE archived = 0 AND kind IN ('phase', 'class');
        CREATE UNIQUE INDEX IF NOT EXISTS vocab_registry_active_triplet
            ON vocab_registry(kind, instrument, verb, target)
            WHERE archived = 0 AND kind = 'triplet';
        """
    )
    con.commit()


def hash_password(password: str) -> str:
    return _HASHER.hash(password)


def create_account(
    path: Path,
    username: str,
    password: str,
    *,
    admin: bool = False,
    reviewer: bool = False,
    annotator: bool = False,
    password_hash: str | None = None,
) -> Account:
    username = username.strip()
    if not username:
        raise ValueError("username is required")
    hashed = password_hash if password_hash is not None else hash_password(password)
    con = connect(path)
    try:
        try:
            cur = con.execute(
                "INSERT INTO users (username, password_hash, admin, reviewer, annotator) "
                "VALUES (?, ?, ?, ?, ?)",
                (username, hashed, int(admin), int(reviewer), int(annotator)),
            )
            con.commit()
        except sqlite3.IntegrityError as exc:
            raise AccountExists(username) from exc
        return Account(
            id=int(cur.lastrowid),
            username=username,
            admin=admin,
            reviewer=reviewer,
            annotator=annotator,
            disabled=False,
        )
    finally:
        con.close()


def _account_from_row(row: sqlite3.Row) -> Account:
    return Account(
        id=row["id"],
        username=row["username"],
        admin=bool(row["admin"]),
        reviewer=bool(row["reviewer"]),
        annotator=bool(row["annotator"]),
        disabled=bool(row["disabled"]),
    )


def set_roles(
    path: Path,
    username: str,
    *,
    admin: bool,
    reviewer: bool,
    annotator: bool,
) -> None:
    con = connect(path)
    try:
        cur = con.execute(
            "UPDATE users SET admin=?, reviewer=?, annotator=? WHERE username=? COLLATE NOCASE",
            (int(admin), int(reviewer), int(annotator), username),
        )
        con.commit()
        if cur.rowcount != 1:
            raise KeyError(username)
    finally:
        con.close()


def set_disabled(path: Path, username: str, disabled: bool) -> None:
    con = connect(path)
    try:
        cur = con.execute(
            "UPDATE users SET disabled=? WHERE username=? COLLATE NOCASE",
            (int(disabled), username),
        )
        con.commit()
        if cur.rowcount != 1:
            raise KeyError(username)
    finally:
        con.close()


def authenticate(path: Path, username: str, password: str) -> Account | None:
    con = connect(path)
    try:
        row = con.execute(
            "SELECT * FROM users WHERE username=? COLLATE NOCASE",
            (username,),
        ).fetchone()
        if row is None or not _HASHER.verify(password, row["password_hash"]):
            return None
        account = _account_from_row(row)
        if account.disabled:
            return None
        return account
    finally:
        con.close()


def create_session(path: Path, user_id: int) -> str:
    token = secrets.token_urlsafe(32)
    con = connect(path)
    try:
        con.execute(
            "INSERT INTO login_sessions (id, user_id, created_at) VALUES (?, ?, ?)",
            (token, user_id, datetime.now(timezone.utc).isoformat()),
        )
        con.commit()
        return token
    finally:
        con.close()


def delete_session(path: Path, token: str) -> None:
    con = connect(path)
    try:
        con.execute("DELETE FROM login_sessions WHERE id=?", (token,))
        con.commit()
    finally:
        con.close()


def account_for_session(path: Path, token: str) -> Account | None:
    con = connect(path)
    try:
        row = con.execute(
            """
            SELECT users.id, users.username, users.admin, users.reviewer,
                   users.annotator, users.disabled
            FROM login_sessions
            JOIN users ON users.id = login_sessions.user_id
            WHERE login_sessions.id = ?
            """,
            (token,),
        ).fetchone()
        if row is None:
            return None
        return _account_from_row(row)
    finally:
        con.close()


def _project_from_row(row: sqlite3.Row) -> Project:
    return Project(id=row["id"], name=row["name"], hospital=row["hospital"])


def _clip_from_row(row: sqlite3.Row) -> RegisteredClip:
    return RegisteredClip(
        id=row["id"],
        project_id=row["project_id"],
        kind=row["kind"],
        path=Path(row["path"]),
    )


def create_project(path: Path, name: str, hospital: str = "") -> Project:
    name = name.strip()
    if not name:
        raise ValueError("name is required")
    hospital = hospital.strip()
    con = connect(path)
    try:
        try:
            cur = con.execute(
                "INSERT INTO projects (name, hospital) VALUES (?, ?)",
                (name, hospital),
            )
            con.commit()
        except sqlite3.IntegrityError as exc:
            raise ProjectExists(name) from exc
        return Project(id=int(cur.lastrowid), name=name, hospital=hospital)
    finally:
        con.close()


def get_project_by_name(path: Path, name: str) -> Project:
    con = connect(path)
    try:
        row = con.execute(
            "SELECT id, name, hospital FROM projects WHERE name=?",
            (name.strip(),),
        ).fetchone()
        if row is None:
            raise ProjectNotFound(name)
        return _project_from_row(row)
    finally:
        con.close()


def get_or_create_project(path: Path, name: str, hospital: str = "") -> Project:
    try:
        return create_project(path, name, hospital)
    except ProjectExists:
        return get_project_by_name(path, name)


def list_projects(path: Path) -> list[Project]:
    con = connect(path)
    try:
        rows = con.execute("SELECT id, name, hospital FROM projects ORDER BY id").fetchall()
        return [_project_from_row(row) for row in rows]
    finally:
        con.close()


def list_registered_clips(path: Path) -> list[RegisteredClip]:
    con = connect(path)
    try:
        rows = con.execute(
            "SELECT id, project_id, kind, path FROM clips ORDER BY rowid"
        ).fetchall()
        return [_clip_from_row(row) for row in rows]
    finally:
        con.close()


def projects_payload(path: Path) -> list[dict]:
    projects = list_projects(path)
    clips_by_project: dict[int, list[dict]] = {}
    for clip in list_registered_clips(path):
        clips_by_project.setdefault(clip.project_id, []).append(
            {"id": clip.id, "kind": clip.kind}
        )
    return [
        {
            "id": project.id,
            "name": project.name,
            "hospital": project.hospital,
            "clips": clips_by_project.get(project.id, []),
        }
        for project in projects
    ]


def _valid_clip_id(clip_id: str) -> str:
    clip_id = clip_id.strip()
    if clip_id in ("", ".", "..") or "/" in clip_id or "\\" in clip_id:
        raise ValueError(f"bad clip id: {clip_id}")
    return clip_id


def register_clip(
    path: Path,
    *,
    project_id: int,
    clip_id: str,
    kind: str,
    media_path: Path,
) -> RegisteredClip:
    clip_id = _valid_clip_id(clip_id)
    kind = kind.strip()
    if not kind:
        raise ValueError("kind is required")
    stored = str(Path(media_path).expanduser().resolve())
    con = connect(path)
    try:
        project = con.execute("SELECT id FROM projects WHERE id=?", (project_id,)).fetchone()
        if project is None:
            raise ProjectNotFound(project_id)
        existing = con.execute("SELECT * FROM clips WHERE id=?", (clip_id,)).fetchone()
        if existing is not None:
            if (
                existing["project_id"] == project_id
                and existing["kind"] == kind
                and existing["path"] == stored
            ):
                return _clip_from_row(existing)
            raise ClipExists(clip_id)
        con.execute(
            "INSERT INTO clips (id, project_id, kind, path) VALUES (?, ?, ?, ?)",
            (clip_id, project_id, kind, stored),
        )
        con.commit()
        return RegisteredClip(
            id=clip_id, project_id=project_id, kind=kind, path=Path(stored)
        )
    finally:
        con.close()


