    _: Account = Depends(require_admin),
) -> dict:
    try:
        get_item(_path(request), vocab_id)
    except RegistryItemNotFound as exc:
        raise _http(exc) from None
    if vocab_id in labels_store.referenced_vocab_ids(request.app.state.settings):
